// Print Route Handler — Life Explorer Student Journal Part 1 (Antarctica)
// Returns raw HTML styled for Letter-size PDF generation (headless Chrome).
// Content mirrors the original journal pack; design is Vibration Fit brand.

export const dynamic = 'force-static'

const BRAND = {
  green: '#39FF14',
  cyan: '#00FFFF',
  navy: '#0B2740',
  navyMid: '#134663',
  ice: '#35B9E6',
  iceSoft: '#BDE7F5',
  paper: '#F4FBFE',
}

function handwritingLines(count: number) {
  return Array.from({ length: count })
    .map(() => `<div class="hw"></div>`)
    .join('')
}

