interface PageOptions {
  number: number
  emoji: string
  title: string
  prompt: string
  body: string
}

function journalPage({ number, emoji, title, prompt, body }: PageOptions) {
  return `
  <section class="sheet page">
    <header class="page-header">
      <span class="chip">EXPEDITION 01 · ANTARCTICA</span>
      <span class="page-badge">${number}</span>
    </header>
    <h2 class="page-title"><span class="page-emoji">${emoji}</span>${title}</h2>
    <p class="page-prompt">${prompt}</p>
    <div class="page-body">${body}</div>
    <footer class="page-footer">
      <span>VIBRATION FIT HOMESCHOOL — LIFE EXPLORER · STUDENT JOURNAL PART 1</span>
      <span>PAGE ${number} OF 10</span>
    </footer>
  </section>`
}

function drawBox(label: string, extraClass = '') {
  return `
  <div class="draw ${extraClass}">
    <span class="draw-label">${label}</span>
    <span class="corner tl">❄️</span>
    <span class="corner br">❄️</span>
  </div>`
}

function buildHtml() {
  const pages: string[] = []

  // Cover
  pages.push(`
  <section class="sheet cover">
    <div class="cover-inner">
      <p class="cover-brand">VIBRATION FIT HOMESCHOOL</p>
      <div class="cover-emoji">🐧</div>
      <h1 class="cover-title">LIFE<br/>EXPLORER</h1>
      <p class="cover-sub">Student Explorer Journal</p>
      <div class="cover-pill">EXPEDITION 01 — ANTARCTICA · PART 1</div>
      <div class="cover-name">
        <p>This journal belongs to</p>
        <div class="cover-name-line"></div>
      </div>
      <p class="cover-quote">Explorers ask questions, notice details,<br/>and share discoveries.</p>
    </div>
    <div class="cover-snow s1">❄️</div>
    <div class="cover-snow s2">❄️</div>
    <div class="cover-snow s3">❄️</div>
    <div class="cover-snow s4">❄️</div>
  </section>`)

  // Page 1 — Welcome Explorer
  pages.push(
    journalPage({
      number: 1,
      emoji: '🧭',
      title: 'Welcome, Explorer',
      prompt:
        'Write your name below. This journal belongs to an explorer. Explorers ask questions, notice details, and share discoveries.',
      body: `
        <div class="callout">
          <span class="callout-emoji">⭐</span>
          <p>My explorer name is…</p>
        </div>
        ${handwritingLines(3)}
        <div class="spacer"></div>
        ${drawBox('Draw your explorer badge here', 'draw-grow')}`,
    })
  )

  // Page 2 — My Expedition Mission
  pages.push(
    journalPage({
      number: 2,
      emoji: '🚀',
      title: 'My Expedition Mission',
      prompt: 'Every expedition starts with a mission. Here is yours:',
      body: `
        <div class="mission">
          <p class="mission-label">MISSION</p>
          <p class="mission-text">Discover what makes Antarctica one of the most amazing places on Earth.</p>
        </div>
        ${drawBox('Draw yourself as an explorer', 'draw-grow')}`,
    })
  )

  // Page 3 — What I Know
  pages.push(
    journalPage({
      number: 3,
      emoji: '🧠',
      title: 'What I Know',
      prompt:
        'Before we begin, draw or write everything you already know about Antarctica. There are no wrong answers!',
      body: `
        ${drawBox('Draw what you know', 'draw-half')}
        <div class="spacer"></div>
        ${handwritingLines(4)}`,
    })
  )

  // Page 4 — What I Wonder
  pages.push(
    journalPage({
      number: 4,
      emoji: '💭',
      title: 'What I Wonder',
      prompt: 'Finish these sentences. Big questions make great explorers!',
      body: `
        <p class="starter">I wonder…</p>
        ${handwritingLines(2)}
        <p class="starter">I&rsquo;m curious about…</p>
        ${handwritingLines(2)}
        <p class="starter">One thing I&rsquo;d love to discover is…</p>
        ${handwritingLines(2)}`,
    })
  )

  // Page 5 — Prediction Page
  pages.push(
    journalPage({
      number: 5,
      emoji: '🤔',
      title: 'Prediction Page',
      prompt: 'Scientists make predictions before they experiment.',
      body: `
        <div class="callout">
          <span class="callout-emoji">🐧</span>
          <p>How do you think penguins stay warm?</p>
        </div>
        ${drawBox('Draw your idea before the experiment', 'draw-grow')}`,
    })
  )

  // Page 6 — Experiment Record
  pages.push(
    journalPage({
      number: 6,
      emoji: '🔬',
      title: 'Experiment Record',
      prompt: 'The Penguin Blubber Experiment — record it like a real scientist.',
      body: `
        <p class="starter">My prediction:</p>
        ${handwritingLines(2)}
        <p class="starter">What happened?</p>
        ${handwritingLines(2)}
        <p class="starter">Why do you think it happened?</p>
        ${handwritingLines(2)}`,
    })
  )

  // Page 7 — Vocabulary Notebook
  const vocab = ['Antarctica', 'Continent', 'Iceberg', 'Penguin', 'Blubber']
  pages.push(
    journalPage({
      number: 7,
      emoji: '📚',
      title: 'Vocabulary Notebook',
      prompt: 'Illustrate each word. Pictures help explorers remember!',
      body: `
        <div class="vocab-grid">
          ${vocab
            .map(
              (word, i) => `
            <div class="vocab-box ${i === 4 ? 'vocab-wide' : ''}">
              <span class="vocab-word">${word}</span>
            </div>`
            )
            .join('')}
        </div>`,
    })
  )

  // Page 8 — Map Explorer (numbered 7-continent outline + word bank)
  pages.push(
    journalPage({
      number: 8,
      emoji: '🗺️',
      title: 'Map Explorer',
      prompt: 'Color Antarctica <strong>blue</strong>. Color where you live <strong>green</strong>. Then write the name of each continent on the blank.',
      body: `
        <div class="map-wrap">
          ${worldMapSvg()}
        </div>
        <div class="word-bank">
          <span class="word-bank-label">WORD BANK</span>
          <span>North America</span>
          <span>South America</span>
          <span>Africa</span>
          <span>Europe</span>
          <span>Asia</span>
          <span>Australia</span>
          <span>Antarctica</span>
        </div>
        <p class="map-hint">Put a ★ on Florida — that&rsquo;s home!</p>`,
    })
  )

  // Page 9 — My Best Discovery
  pages.push(
    journalPage({
      number: 9,
      emoji: '🏆',
      title: 'My Best Discovery',
      prompt:
        'Draw your favorite thing you learned this week and write one sentence about it.',
      body: `
        ${drawBox('My favorite discovery', 'draw-half')}
        <div class="spacer"></div>
        ${handwritingLines(3)}`,
    })
  )

  // Page 10 — What I Still Wonder
  pages.push(
    journalPage({
      number: 10,
      emoji: '✨',
      title: 'What I Still Wonder',
      prompt:
        'Every explorer finishes one expedition with new questions. What do you still wonder?',
      body: `
        ${handwritingLines(5)}
        <div class="finish">
          <span class="finish-emoji">🐧</span>
          <p class="finish-title">Expedition 1 · Part 1 complete!</p>
          <p class="finish-sub">Your new questions are the start of the next adventure.</p>
        </div>`,
    })
  )

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<title>Life Explorer — Student Journal Part 1 — Antarctica</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  html, body { background: #e5e7eb; font-family: 'Poppins', sans-serif; color: ${BRAND.navy}; }

  @page { size: letter; margin: 0; }
  .sheet {
    width: 8.5in;
    height: 11in;
    background: white;
    margin: 0 auto;
    page-break-after: always;
    break-after: page;
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }
  @media screen {
    body { padding: 24px 0; }
    .sheet { margin-bottom: 24px; box-shadow: 0 8px 32px rgba(0,0,0,0.35); border-radius: 4px; }
  }

  /* ============ Cover ============ */
  .cover {
    background:
      radial-gradient(120% 90% at 80% -10%, rgba(0,255,255,0.16) 0%, transparent 55%),
      radial-gradient(120% 90% at 10% 110%, rgba(57,255,20,0.12) 0%, transparent 55%),
      linear-gradient(160deg, #0a0a0a 0%, #0B2740 62%, #134663 100%);
    align-items: center;
    justify-content: center;
    text-align: center;
  }
  .cover-inner { position: relative; z-index: 2; padding: 0.9in 0.8in; display: flex; flex-direction: column; align-items: center; height: 100%; justify-content: center; gap: 0.22in; }
  .cover-brand { color: ${BRAND.green}; letter-spacing: 0.35em; font-size: 12px; font-weight: 600; }
  .cover-emoji { font-size: 84px; line-height: 1; }
  .cover-title {
    font-size: 92px; font-weight: 800; line-height: 0.95; letter-spacing: 0.02em;
    background: linear-gradient(100deg, ${BRAND.green} 0%, ${BRAND.cyan} 100%);
    -webkit-background-clip: text; background-clip: text; color: transparent;
  }
  .cover-sub { color: #E8F6FB; font-size: 24px; font-weight: 500; letter-spacing: 0.06em; }
  .cover-pill {
    border: 2px solid ${BRAND.cyan}; color: ${BRAND.cyan};
    border-radius: 999px; padding: 10px 26px; font-size: 15px; font-weight: 700; letter-spacing: 0.14em;
  }
  .cover-name { margin-top: 0.25in; width: 5.4in; }
  .cover-name p { color: ${BRAND.iceSoft}; font-size: 15px; margin-bottom: 18px; letter-spacing: 0.08em; }
  .cover-name-line { border-bottom: 3px solid ${BRAND.green}; height: 0.5in; }
  .cover-quote { color: #9CC7DA; font-size: 14px; line-height: 1.7; margin-top: 0.15in; }
  .cover-snow { position: absolute; opacity: 0.5; z-index: 1; }
  .s1 { top: 0.6in; left: 0.7in; font-size: 34px; }
  .s2 { top: 1.6in; right: 0.8in; font-size: 22px; }
  .s3 { bottom: 1.4in; left: 1.1in; font-size: 24px; }
  .s4 { bottom: 0.7in; right: 1.2in; font-size: 36px; }

  /* ============ Journal pages ============ */
  .page { padding: 0.55in 0.65in 0.45in; background: linear-gradient(180deg, ${BRAND.paper} 0%, #FFFFFF 26%); }
  .page-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.28in; }
  .chip {
    background: ${BRAND.navy}; color: ${BRAND.green};
    font-size: 11px; font-weight: 700; letter-spacing: 0.16em;
    border-radius: 999px; padding: 7px 16px;
  }
  .page-badge {
    width: 42px; height: 42px; border-radius: 50%;
    background: linear-gradient(135deg, ${BRAND.green}, ${BRAND.cyan});
    color: ${BRAND.navy}; font-weight: 800; font-size: 19px;
    display: flex; align-items: center; justify-content: center;
  }
  .page-title { font-size: 34px; font-weight: 800; letter-spacing: -0.01em; display: flex; align-items: center; gap: 14px; }
  .page-emoji { font-size: 34px; }
  .page-prompt { color: ${BRAND.navyMid}; font-size: 15px; line-height: 1.6; margin-top: 10px; max-width: 6.4in; }
  .page-body { flex: 1; display: flex; flex-direction: column; margin-top: 0.28in; min-height: 0; }
  .page-footer {
    display: flex; justify-content: space-between; align-items: center;
    border-top: 2px solid ${BRAND.iceSoft}; padding-top: 12px; margin-top: 0.25in;
    font-size: 9px; font-weight: 600; letter-spacing: 0.14em; color: #7FA8BC;
  }

  /* Handwriting guide lines (grade 1: solid / dashed / solid) */
  .hw {
    height: 0.62in; margin-bottom: 0.16in; position: relative;
    border-top: 2.5px solid ${BRAND.navy}; border-bottom: 2.5px solid ${BRAND.navy};
  }
  .hw::after {
    content: ''; position: absolute; top: 50%; left: 0; right: 0;
    border-top: 2px dashed ${BRAND.iceSoft};
  }

  /* Drawing boxes */
  .draw {
    border: 3.5px dashed ${BRAND.ice}; border-radius: 22px;
    background: linear-gradient(180deg, #FBFEFF 0%, ${BRAND.paper} 100%);
    position: relative; display: flex; align-items: flex-end; justify-content: center;
  }
  .draw-grow { flex: 1; min-height: 3in; }
  .draw-half { height: 4.1in; }
  .draw-label {
    margin-bottom: 16px; background: white; border: 2px solid ${BRAND.iceSoft};
    color: ${BRAND.navyMid}; border-radius: 999px; padding: 6px 18px;
    font-size: 12px; font-weight: 600; letter-spacing: 0.04em;
  }
  .corner { position: absolute; font-size: 20px; opacity: 0.7; }
  .corner.tl { top: 12px; left: 16px; }
  .corner.br { bottom: 12px; right: 16px; }

  /* Callouts and mission */
  .callout {
    display: flex; align-items: center; gap: 16px;
    background: ${BRAND.navy}; border-radius: 18px; padding: 18px 22px; margin-bottom: 0.28in;
  }
  .callout-emoji { font-size: 30px; }
  .callout p { color: white; font-size: 19px; font-weight: 600; }
  .mission {
    border: 3px solid ${BRAND.green}; border-radius: 22px;
    background: linear-gradient(135deg, rgba(57,255,20,0.07), rgba(0,255,255,0.07));
    padding: 24px 28px; margin-bottom: 0.3in; text-align: center;
  }
  .mission-label { color: #199D67; font-size: 12px; font-weight: 800; letter-spacing: 0.3em; margin-bottom: 8px; }
  .mission-text { font-size: 22px; font-weight: 700; line-height: 1.45; }

  .starter { font-size: 17px; font-weight: 700; color: ${BRAND.navyMid}; margin: 0.1in 0 0.14in; }
  .starter::before { content: '✏️  '; }
  .spacer { height: 0.25in; }

  /* Vocabulary grid */
  .vocab-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.22in; flex: 1; }
  .vocab-box {
    border: 3px dashed ${BRAND.ice}; border-radius: 18px;
    background: linear-gradient(180deg, #FBFEFF 0%, ${BRAND.paper} 100%);
    position: relative; min-height: 2.1in;
  }
  .vocab-wide { grid-column: span 2; }
  .vocab-word {
    position: absolute; top: -14px; left: 18px;
    background: ${BRAND.navy}; color: ${BRAND.cyan};
    border-radius: 999px; padding: 5px 16px; font-size: 14px; font-weight: 700; letter-spacing: 0.05em;
  }

  /* Checklist */
  .checklist { list-style: none; margin-bottom: 0.28in; }
  .checklist li {
    font-size: 16px; padding: 9px 0 9px 40px; position: relative; color: ${BRAND.navyMid};
  }
  .checklist li::before {
    content: ''; position: absolute; left: 0; top: 8px;
    width: 22px; height: 22px; border: 2.5px solid ${BRAND.ice}; border-radius: 7px; background: white;
  }

  /* Finish block */
  .finish {
    margin-top: auto; text-align: center;
    border: 3px solid ${BRAND.cyan}; border-radius: 22px;
    background: linear-gradient(135deg, rgba(0,255,255,0.08), rgba(57,255,20,0.08));
    padding: 26px;
  }
  .finish-emoji { font-size: 40px; }
  .finish-title { font-size: 22px; font-weight: 800; margin-top: 8px; }
  .finish-sub { color: ${BRAND.navyMid}; font-size: 14px; margin-top: 6px; }

  /* Map Explorer */
  .map-wrap {
    border: 3px solid ${BRAND.iceSoft}; border-radius: 22px;
    overflow: hidden; background: #E8F6FB; flex: 1; min-height: 0;
    display: flex; align-items: center; justify-content: center;
    padding: 8px;
  }
  .world-map { width: 100%; height: auto; max-height: 5.15in; display: block; }
  .word-bank {
    display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
    margin-top: 0.18in; padding: 12px 14px;
    border: 2px dashed ${BRAND.ice}; border-radius: 16px; background: white;
  }
  .word-bank-label {
    background: ${BRAND.navy}; color: ${BRAND.green};
    font-size: 10px; font-weight: 800; letter-spacing: 0.16em;
    border-radius: 999px; padding: 5px 12px; margin-right: 4px;
  }
  .word-bank > span:not(.word-bank-label) {
    font-size: 13px; font-weight: 600; color: ${BRAND.navyMid};
    background: ${BRAND.paper}; border: 1.5px solid ${BRAND.iceSoft};
    border-radius: 999px; padding: 4px 12px;
  }
  .map-hint {
    margin-top: 0.12in; font-size: 13px; font-weight: 600;
    color: ${BRAND.navyMid}; text-align: center;
  }
</style>
</head>
<body>
${pages.join('\n')}
</body>
</html>`
}

export async function GET() {
  return new Response(buildHtml(), {
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  })
}
